const fs=require('fs'),path=require('path');
const root=path.resolve(__dirname,'../../..'),dir=path.resolve(__dirname,'..');
const read=p=>fs.readFileSync(path.join(root,p),'utf8');
const line=(p,s)=>{const i=read(p).split(/\r?\n/).findIndex(l=>l.includes(s));if(i<0)throw Error('Missing evidence '+p+' '+s);return i+1};
const evidence=(p,s)=>`${p}:${line(p,s)}`;
const findings=[];
function finding(id,severity,category,title,file,needle,problem,impact,recommendation,effort,reproduce,verification){findings.push({id,severity,category,title,file,line:line(file,needle),status:'PROBLEMA ENCONTRADO',current_state:problem,problem,impact,recommendation,effort,reproduce,verification})}
